    for (var i = 0; i < cells.length; i++) { cells[i].style.backgroundColor = ''; cells[i].style.outline = ''; cells[i].style.outlineOffset = ''; }
    // Clear the row background
    var rows = document.querySelectorAll('tr[data-row]');
